package psx.exporter;

import java.awt.image.BufferedImage;import java.lang.invoke.*;import java.lang.reflect.Modifier;import java.util.*;import java.util.function.BooleanSupplier;

/** Original-worker renderer binding. Snapshot request/arming happens before
 * closure; only completed images owned by the existing recorder worker enter
 * the cache. An unavailable image rejects recall without blocking rendering. */
final class FmcRenderingAccess {
    private final FmcInitialization.Context context;private final BooleanSupplier qualified;private final MethodHandle roots,boxes,visible,powered,publish,clear,shadowRead;private final Class<?> nd;
    private final Object[] bound,boundBoxes;private final FmcRenderingCache.Drawing drawing;private long token;private BufferedImage[][] nativeImages;
    private FmcRenderingAccess(FmcInitialization.Context context,BooleanSupplier qualified,boolean eager)throws Throwable{
        this.context=context;this.qualified=qualified;nd=context.owner("NavigationDisplay");var owner=context.owner("IntegratedDisplaySystem");roots=method(owner,FmcRenderingPrepare.ROOTS);boxes=method(owner,FmcRenderingPrepare.BOX_ROOTS);visible=method(owner,FmcRenderingPrepare.VISIBLE);
        for(var field:List.of(FmcRenderingPrepare.SHADOW,FmcRenderingPrepare.SHADOW_EPOCH)){var f=nd.getDeclaredField(field);require(f.isSynthetic()&&f.getModifiers()==(Modifier.PRIVATE|Modifier.VOLATILE|0x1000)&&f.getType()==(field.equals(FmcRenderingPrepare.SHADOW)?BufferedImage[].class:long.class),"exact immutable native raster field");}
        var setter=nd.getDeclaredMethod(FmcRenderingPrepare.SHADOW_PUBLISH,Object.class,long.class,BufferedImage[].class);var reset=nd.getDeclaredMethod(FmcRenderingPrepare.SHADOW_CLEAR,Object.class);for(var bridge:List.of(setter,reset))require(bridge.isSynthetic()&&Modifier.isPublic(bridge.getModifiers())&&Modifier.isStatic(bridge.getModifiers())&&bridge.getReturnType()==void.class,"exact native raster worker bridge");var shadowLookup=MethodHandles.privateLookupIn(nd,MethodHandles.lookup());publish=shadowLookup.findStatic(nd,FmcRenderingPrepare.SHADOW_PUBLISH,MethodType.methodType(void.class,Object.class,long.class,BufferedImage[].class));clear=shadowLookup.findStatic(nd,FmcRenderingPrepare.SHADOW_CLEAR,MethodType.methodType(void.class,Object.class));var reader=nd.getDeclaredMethod(FmcRenderingPrepare.SHADOW_READ,Object.class);require(reader.isSynthetic()&&Modifier.isPublic(reader.getModifiers())&&Modifier.isStatic(reader.getModifiers())&&reader.getReturnType()==BufferedImage[].class,"exact native raster readback");shadowRead=shadowLookup.findStatic(nd,FmcRenderingPrepare.SHADOW_READ,MethodType.methodType(BufferedImage[].class,Object.class));
        var p=nd.getDeclaredMethod(FmcRenderingPrepare.POWERED,Object.class);require(p.isSynthetic()&&Modifier.isPublic(p.getModifiers())&&Modifier.isStatic(p.getModifiers())&&p.getReturnType()==boolean.class,"exact power bridge");powered=MethodHandles.privateLookupIn(nd,MethodHandles.lookup()).findStatic(nd,FmcRenderingPrepare.POWERED,MethodType.methodType(boolean.class,Object.class));bound=(Object[])roots.invokeExact();boundBoxes=(Object[])boxes.invokeExact();require(bound.length==4&&boundBoxes.length==6,"four native renderers/six display boxes");for(Object value:bound)require(nd.isInstance(value),"current native renderer type");var box=context.owner("IntegratedDisplaySystem$Box");for(Object value:boundBoxes)require(box.isInstance(value),"current native display box type");current();drawing=FmcRenderingCaptureAccess.bind(context,qualified,bound);if(eager)token=FmcRenderingCache.request(Observer.terrainEpoch(),bound,drawing);
    }
    static FmcRenderingAccess bind(FmcInitialization.Context context,BooleanSupplier qualified)throws Throwable{require(context.current()&&qualified.getAsBoolean()&&!FmcExclusion.admissionClosed(),"open worker binding");return new FmcRenderingAccess(context,qualified,true);}
    /** Resolve roots/drawing before metadata admission; request pixels only after
     * all binding preflight has succeeded and a releasable owner exists. */
    static FmcRenderingAccess prepare(FmcInitialization.Context context,BooleanSupplier qualified)throws Throwable{require(context.current()&&qualified.getAsBoolean()&&!FmcExclusion.admissionClosed(),"open worker preparation");return new FmcRenderingAccess(context,qualified,false);}
    private static MethodHandle method(Class<?> owner,String name)throws ReflectiveOperationException{var m=owner.getDeclaredMethod(name);require(m.isSynthetic()&&Modifier.isPublic(m.getModifiers())&&Modifier.isStatic(m.getModifiers())&&m.getReturnType()==Object[].class,"exact readonly bridge");return MethodHandles.privateLookupIn(owner,MethodHandles.lookup()).findStatic(owner,name,MethodType.methodType(Object[].class));}
    void arm()throws Throwable{current();require(!FmcExclusion.admissionClosed(),"arming must precede closure");if(token==0)token=FmcRenderingCache.request(Observer.terrainEpoch(),bound,drawing);var selected=new ArrayList<Object>();for(Object value:bound)if((boolean)powered.invokeExact(value))selected.add(value);BufferedImage[][] images=new BufferedImage[4][];for(int i=0;i<4;i++)images[i]=FmcRenderingCache.nativeImage(token,bound[i]);FmcRenderingCache.arm(token,selected.toArray());long epoch=Observer.terrainEpoch();for(int i=0;i<4;i++)if(images[i]!=null){require(images[i].length==2&&images[i][0]!=null&&images[i][1]!=null,"complete immutable native raster");publish.invokeExact(bound[i],epoch,images[i]);}nativeImages=images;shadow();current();}
    void verify()throws Throwable{current();shadow();require(FmcRenderingCache.armed(token),"complete images must remain armed");for(Object value:bound)if((boolean)powered.invokeExact(value))require(FmcRenderingCache.complete(token,value),"every powered ND root requires its own complete pixels, including hidden roots");current();}
    private void shadow()throws Throwable{require(nativeImages!=null,"worker-owned native raster published");for(int i=0;i<4;i++)require((BufferedImage[])shadowRead.invokeExact(bound[i])==nativeImages[i],"native raster preimage replaced");}
    Object[] receivers(){var result=new Object[10];System.arraycopy(bound,0,result,0,4);System.arraycopy(boundBoxes,0,result,4,6);return result;}
    void release()throws Throwable{require(!FmcExclusion.admissionClosed(),"native raster clears after reopen");if(token==0)return;Throwable failure=null;for(Object owner:bound)try{clear.invokeExact(owner);}catch(Throwable cleanup){if(failure==null)failure=cleanup;else failure.addSuppressed(cleanup);}try{FmcRenderingCache.clear(token);}catch(Throwable cleanup){if(failure==null)failure=cleanup;else failure.addSuppressed(cleanup);}if(failure!=null)throw failure;}
    private void current()throws Throwable{require(context.current()&&qualified.getAsBoolean(),"renderer lifecycle changed");Object[] actual=(Object[])roots.invokeExact();require(actual.length==bound.length,"renderer root roster");for(int i=0;i<4;i++)require(actual[i]==bound[i],"native renderer root replaced");actual=(Object[])boxes.invokeExact();require(actual.length==6,"display box roster");for(int i=0;i<6;i++)require(actual[i]==boundBoxes[i],"native display box replaced");}
    private static void require(boolean yes,String why){if(!yes)throw new IllegalStateException("FMC rendering binding "+why);}
}
